import numpy as np

# Board size for simulation
N = 8
BOARD = np.zeros((N, N), dtype=int) # 0: Empty, 1: Knight, 2: Queen

def is_valid(r, c):
    return 0 <= r < N and 0 <= c < N

def get_knight_moves(r, c):
    moves = []
    knight_deltas = [
        (2, 1), (2, -1), (-2, 1), (-2, -1),
        (1, 2), (1, -2), (-1, 2), (-1, -2)
    ]
    for dr, dc in knight_deltas:
        nr, nc = r + dr, c + dc
        if is_valid(nr, nc):
            moves.append((nr, nc))
    return moves

def is_safe_knight_placement(r, c, board):
    """Checks if placing a knight at (r, c) is safe (i.e., does not attack any existing knights)."""
    # Check if (r, c) is attacked by any existing knight
    for r_k in range(N):
        for c_k in range(N):
            if board[r_k, c_k] == 1: # If there is a knight at (r_k, c_k)
                # Check if (r, c) is reachable from (r_k, c_k)
                # This is equivalent to checking if (r_k, c_k) is reachable from (r, c)
                if (abs(r - r_k) == 1 and abs(c - c_k) == 2) or \
                   (abs(r - r_k) == 2 and abs(c - c_k) == 1):
                    return False
    return True

def get_available_knight_spots(board):
    """Returns a list of empty spots where a knight can be placed safely."""
    available = []
    for r in range(N):
        for c in range(N):
            if board[r, c] == 0:
                # For the first knight, the constraint is trivially met, 
                # but we must check against existing knights (if any)
                if is_safe_knight_placement(r, c, board):
                    available.append((r, c))
    return available

